import unittest
from candidate import remove_duplicates

class TestRemoveDuplicates(unittest.TestCase):
    def test_remove_duplicates_all_unique(self):
        self.assertListEqual(remove_duplicates([1, 2, 3]), [1, 2, 3])

    def test_remove_duplicates_all_duplicates(self):
        self.assertListEqual(remove_duplicates([1, 1, 2, 2]), [])

    def test_remove_duplicates_mixed(self):
        self.assertListEqual(remove_duplicates([1, 2, 2, 3, 4, 4, 5]), [1, 3, 5])

    def test_remove_duplicates_preserve_order(self):
        data = [10, 20, 20, 30, 40, 40, 50]
        self.assertListEqual(remove_duplicates(data), [10, 30, 50])

    def test_remove_duplicates_empty_list(self):
        self.assertListEqual(remove_duplicates([]), [])

    def test_remove_duplicates_single_element(self):
        self.assertListEqual(remove_duplicates([42]), [42])

    def test_remove_duplicates_negative_and_zero(self):
        self.assertListEqual(remove_duplicates([-1, 0, 0, -1, 2]), [2])

    def test_remove_duplicates_large_numbers(self):
        self.assertListEqual(remove_duplicates([10**12, 10**12, 10**12 + 1]), [10**12 + 1])

    def test_remove_duplicates_input_unchanged(self):
        original = [1, 2, 2, 3]
        original_copy = original.copy()
        remove_duplicates(original)
        self.assertListEqual(original, original_copy)

    def test_remove_duplicates_non_int_elements(self):
        data = ['a', 'b', 'a', 3]
        self.assertListEqual(remove_duplicates(data), ['b', 3])

    def test_remove_duplicates_input_is_none(self):
        with self.assertRaises(TypeError):
            remove_duplicates(None)

    def test_remove_duplicates_input_not_iterable(self):
        with self.assertRaises(TypeError):
            remove_duplicates(5)

    def test_remove_duplicates_input_is_generator(self):
        gen = (x for x in [1, 2, 2, 3])
        self.assertListEqual(remove_duplicates(gen), [1, 3])

    def test_remove_duplicates_none_elements_in_list(self):
        self.assertListEqual(remove_duplicates([1, None, None, 2]), [1, 2])

    def test_remove_duplicates_returns_new_list(self):
        data = [1, 2, 2, 3]
        result = remove_duplicates(data)
        self.assertIsNot(result, data)

    def test_remove_duplicates_duplicate_float(self):
        self.assertListEqual(remove_duplicates([1.0, 1.0, 2]), [2])

    def test_remove_duplicates_duplicate_string(self):
        self.assertListEqual(remove_duplicates(['x', 'y', 'x', 'z']), ['y', 'z'])

if __name__ == '__main__':
    unittest.main()
